# Accepted natively although --help does not list them. Each name is checked
# against the parser in src/main.cpp.
UNLISTED = {
    '--del': 'same as --delete-during',
    '--delete-before': 'delete extraneous entries before transferring',
    '--delete-during': 'delete extraneous entries while transferring',
    '--delete-delay': 'find deletions during the transfer, delete afterwards',
    '--devices': 'preserve device files (part of -D)',
    '--specials': 'preserve special files (part of -D)',
    '--ignore-non-existing': 'same as --existing',
    '--info': 'progress2, progress0, stats2 or stats0, comma separated',
    '--compress-choice': 'zstd or none (alias --zc)',
    '--clone': 'allow copy-on-write clones again after --no-clone',
    '--no-OPTION': 'turn off a flag, for example --no-perms, --no-times, --no-D',
}
